import {referenceIndex} from '../reference/puppet.js';
import {bevelPathData} from '../scene/bevel.js';
import {textureSVG} from '../scene/texture.js';
import {shadowSVG} from '../scene/shadow.js';
import {fitMesh} from '../scene/contour.js';
import {strokeOutline} from '../scene/strokes.js';
import {meshImage} from '../scene/mesh.js';
import {evaluated,activeTracks} from '../animation/evaluate.js';
import {matrix,localBounds} from '../scene/matrix.js';
export const NS='http://www.w3.org/2000/svg';
export const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function pathData(n){if(n.nodes?.some(p=>p.bevelRadius>0))return bevelPathData(n);if(n.rawPath)return n.rawPath;const pts=n.nodes;if(!pts.length)return '';const segment=(a,b)=>a.out||b.in?` C ${(a.out||a).x} ${(a.out||a).y} ${(b.in||b).x} ${(b.in||b).y} ${b.x} ${b.y}`:` L ${b.x} ${b.y}`;let d='',first=pts[0],prev=null;for(const p of pts){if(!prev||p.move){first=p;d+=` M ${p.x} ${p.y}`;}else d+=segment(prev,p);if(p.close){if(p.out||first.in)d+=segment(p,first);d+=' Z';prev=null;}else prev=p;}if(n.closed&&prev&&pts.length>1)d+=segment(prev,first)+' Z';return d.trim();}
export function artwork(n,time,interactive=false,inheritedLock=false){if(!n.visible)return '';const v=evaluated(n,time),m=matrix(v);if(v.mesh?.contour&&!activeTracks(n,time).mesh?.length&&activeTracks(n,time).nodes?.length&&v.mesh.geometryTime!==time)v.mesh=fitMesh(n,time,v.mesh);let body='';if(n.type==='group')body=n.children.map(c=>artwork(c,time,interactive,inheritedLock||n.locked)).join('');else if(n.type==='image'){const frame=n.referenceFrames?referenceIndex(n.referenceFrames,time):-1;if(n.referenceFrames&&frame<0)return '';body=`<image href="${escape(n.referenceFrames?.frames[frame]||n.imageSrc||'')}" width="${v.width}" height="${v.height}" preserveAspectRatio="xMidYMid meet"/>`;}else if(n.type==='rectangle')body=`<rect width="${v.width}" height="${v.height}" rx="${v.radius||0}"/>`;else if(n.type==='ellipse')body=`<ellipse cx="${v.width/2}" cy="${v.height/2}" rx="${v.width/2}" ry="${v.height/2}"/>`;else if(n.type==='text')body=`<text x="${v.align==='center'?v.width/2:v.align==='right'?v.width:0}" y="${v.fontSize}" font-family="${escape(v.font)}" font-size="${v.fontSize}" text-anchor="${v.align==='center'?'middle':v.align==='right'?'end':'start'}">${escape(v.text)}</text>`;else body=`<path d="${escape(pathData(v))}" />`;const originalShape=body;if(v.strokeProfile&&v.strokeProfile!=='uniform'&&v.strokeWidth>0&&n.type!=='text'&&n.type!=='group'){const b=localBounds(v),pad=v.strokeWidth*2,id='stroke-'+n.id,outline=strokeOutline(v.nodes?.some(p=>p.bevelRadius>0)?{...v,rawPath:pathData(v)}:v),dash=v.lineStyle==='dashed'?`${v.strokeWidth*4} ${v.strokeWidth*2}`:v.lineStyle==='dotted'?`0 ${v.strokeWidth*2}`:'';body=`<g stroke="none">${body}</g>${dash?`<defs><mask id="${id}" maskUnits="userSpaceOnUse" x="${b.x-pad}" y="${b.y-pad}" width="${b.width+pad*2}" height="${b.height+pad*2}">${originalShape.replace(/<(rect|ellipse|path)\b/,`<$1 fill="none" stroke="white" stroke-width="${v.strokeWidth*2}" stroke-dasharray="${dash}" stroke-linecap="${v.lineCap||'round'}"`)}</mask></defs>`:''}<path d="${outline}" fill="${escape(v.stroke)}" stroke="none" ${dash?`mask="url(#${id})"`:''}/>`;}if(v.mesh&&n.type!=='group'&&n.type!=='text'){const shape=originalShape,outline=body,b=v.mesh.bounds,clip='mesh-'+n.id;body=`${shape}<defs><clipPath id="${clip}">${shape.replace(/<(rect|ellipse|path)\b/,'<$1 clip-rule="'+(v.fillRule==='evenodd'?'evenodd':'nonzero')+'" fill="white" stroke="none"')}</clipPath></defs><g fill="none" stroke="none" clip-path="url(#${clip})"><image href="${meshImage(v.mesh)}" x="${b.x}" y="${b.y}" width="${b.width}" height="${b.height}" preserveAspectRatio="none"/></g><g fill="none">${outline}</g>`;}if(v.texture&&n.type!=='group'&&n.type!=='text'){const image=textureSVG(v.texture,localBounds(v),originalShape,n.id,!!v.mesh,v.fillRule);if(image){const stroke=v.strokeProfile&&v.strokeProfile!=='uniform'&&v.strokeWidth>0?`<path d="${strokeOutline(v.nodes?.some(p=>p.bevelRadius>0)?{...v,rawPath:pathData(v)}:v)}" fill="${escape(v.stroke)}" stroke="none" ${['dashed','dotted'].includes(v.lineStyle)?`mask="url(#stroke-${n.id})"`: ''}/>`:`<g fill="none">${originalShape}</g>`;body+=image+stroke;}}const shadow=shadowSVG(v);return `${shadow.defs}<g ${shadow.attribute} ${interactive?`data-id="${n.id}" style="pointer-events:${inheritedLock||n.locked?'none':'auto'}"`:''} transform="matrix(${m.join(' ')})" opacity="${v.opacity}" fill-rule="${v.fillRule==='evenodd'?'evenodd':'nonzero'}" fill="${escape(v.fill)}" stroke="${escape(v.stroke)}" stroke-width="${v.strokeWidth}" stroke-linecap="${['round','square','butt'].includes(v.lineCap)?v.lineCap:'round'}" stroke-linejoin="${['round','miter','bevel'].includes(v.lineJoin)?v.lineJoin:'round'}" stroke-dasharray="${v.lineStyle==='dashed'?`${Math.max(1,v.strokeWidth)*4} ${Math.max(1,v.strokeWidth)*2}`:v.lineStyle==='dotted'?`0 ${Math.max(1,v.strokeWidth)*2}`:'none'}">${body}</g>`;}
export function sceneSVG(p,time,ids,transparent=false){const prune=n=>ids.includes(n.id)?n:{...n,children:(n.children||[]).map(prune).filter(Boolean),type:'group'};const keep=n=>ids.includes(n.id)||n.children?.some(keep);const exportable=list=>list.filter(n=>!n.reference||n.exportIncluded).map(n=>n.type==='group'?{...n,children:exportable(n.children)}:n);const nodes=ids?p.layers.filter(keep).map(prune):exportable(p.layers);return `<svg xmlns="${NS}" width="${p.width}" height="${p.height}" viewBox="0 0 ${p.width} ${p.height}">${transparent?'':`<rect width="100%" height="100%" fill="${escape(p.background)}"/>`}${nodes.map(n=>artwork(n,time)).join('')}</svg>`;}
export class PreviewRenderer{constructor(svg){this.svg=svg;this.cache='';}render(p,time,onion){const ghost=(t,index)=>p.layers.filter(n=>!n.reference).map(n=>artwork(n,t)).join('').replace(/id="([^"]+)"/g,(_,id)=>'id="onion-'+index+'-'+id+'"').replace(/url\(#([^\)]+)\)/g,(_,id)=>'url(#onion-'+index+'-'+id+')');const ghosts=onion?.enabled?Array.from({length:onion.count||1},(_,i)=>i+1).flatMap(i=>[time-i/p.fps,time+i/p.fps].map((t,j)=>t>=0&&t<p.duration?`<g data-onion="${j?'next':'previous'}" opacity="${onion.opacity/i}" style="pointer-events:none;filter:grayscale(1)">${ghost(t,i+'-'+j)}</g>`:'' )).join(''):'';const markup=`<rect class="stage-paper" width="${p.width}" height="${p.height}" fill="${escape(p.background)}"/>${ghosts}${p.layers.map(n=>artwork(n,time,true)).join('')}`;this.svg.setAttribute('viewBox',`0 0 ${p.width} ${p.height}`);if(markup!==this.cache){const template=document.createElementNS(NS,'svg');template.innerHTML=markup;const patch=(current,next)=>{if(current.nodeType!==next.nodeType||current.nodeName!==next.nodeName){current.replaceWith(next.cloneNode(true));return;}if(current.nodeType===3){if(current.textContent!==next.textContent)current.textContent=next.textContent;return;}for(const attr of [...current.attributes])if(!next.hasAttribute(attr.name))current.removeAttribute(attr.name);for(const attr of [...next.attributes])if(current.getAttribute(attr.name)!==attr.value)current.setAttribute(attr.name,attr.value);const a=[...current.childNodes],b=[...next.childNodes];for(let i=0;i<Math.max(a.length,b.length);i++){if(!a[i])current.appendChild(b[i].cloneNode(true));else if(!b[i])a[i].remove();else patch(a[i],b[i]);}};const a=[...this.svg.childNodes],b=[...template.childNodes];for(let i=0;i<Math.max(a.length,b.length);i++){if(!a[i])this.svg.appendChild(b[i].cloneNode(true));else if(!b[i])a[i].remove();else patch(a[i],b[i]);}this.cache=markup;}}}
